import type { GuiaExercicio } from './guiasExercicios'

const guias: Record<string, GuiaExercicio> = {}
const chave = (nome: string) => nome.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('pt-BR').replace(/\s+/g, ' ').trim()
function incluir(nomes: string, preparacao: string, passos: string[], evite: [string, string]) {
  for (const nome of nomes.split('|')) {
    if (guias[chave(nome)]) throw new Error(`Guia duplicado: ${nome}`)
    guias[chave(nome)] = { preparacao, passos, evite }
  }
}

// Variacoes explicitamente listadas: nenhuma regra aproxima cadastros desconhecidos.
for (const [nome, banco, carga] of [
  ['Supino inclinado com barra', 'inclinado de forma moderada', 'barra'],
  ['Supino declinado com barra', 'declinado, com apoio seguro para as pernas', 'barra'],
  ['Supino declinado com halteres', 'declinado, com apoio seguro para as pernas', 'halteres'],
] as const) incluir(nome, `Use um banco ${banco}. Posicione a carga com ajuda se necessário, mantendo cabeça, costas e quadril apoiados.`,
  [`Segure ${carga === 'barra' ? 'a barra com as mãos fechadas, usando travas e auxílio para retirar do suporte' : 'os halteres de cada lado do peito, com punhos alinhados aos antebraços'}.`, 'Abaixe a carga lentamente em direção ao peito, mantendo as mãos acima dos cotovelos.', 'Empurre para cima sem levantar o quadril ou perder os apoios.', 'Finalize colocando a carga em segurança; peça ajuda antes de perder o controle.'], ['Não quique a carga sobre o peito.', 'Não use uma amplitude que provoque dor nos ombros.'])
for (const [nome, ajuste] of [
  ['Supino reto no Smith', 'reto'], ['Supino inclinado no Smith', 'moderadamente inclinado'], ['Supino declinado no Smith', 'declinado com apoio para as pernas'],
] as const) incluir(nome, `Posicione um banco ${ajuste} sob o Smith e confira o trajeto da barra sem carga. Ajuste os limitadores antes de começar.`,
  ['Deite com costas e quadril apoiados; coloque as mãos de modo que os antebraços fiquem próximos da vertical.', 'Destrave a barra e abaixe lentamente em direção ao peito, seguindo o trilho.', 'Empurre sem perder os apoios; não force o corpo a acompanhar um trajeto desconfortável.', 'Gire e confira o encaixe dos ganchos antes de retirar as mãos.'], ['Não comece sem regular as travas de segurança.', 'Não levante o quadril para alcançar ou empurrar a barra.'])
for (const [nome, altura] of [['Supino inclinado na máquina', 'parte superior do peito'], ['Supino declinado na máquina', 'parte inferior do peito']] as const) incluir(nome,
  `Regule assento e amplitude conforme o fabricante para que as alças correspondam à ${altura}. Mantenha os pés e as costas apoiados.`,
  ['Segure as alças com punhos estáveis e mãos alinhadas aos cotovelos.', 'Empurre acompanhando o arco da máquina sem projetar a cabeça.', 'Retorne devagar até a amplitude que consegue controlar.'], ['Não descole as costas do encosto.', 'Não deixe as placas baterem na volta.'])
incluir('Supino reto com pausa', 'Use barra e banco reto, com limitadores ou ajuda de outra pessoa. Apoie os pés e mantenha o tronco estável.', ['Retire a barra e abaixe com controle em direção ao peito.', 'Faça a pausa prevista no treino, sem relaxar os braços nem quicar a barra.', 'Empurre para cima mantendo quadril e costas apoiados.', 'Recoloque a barra nos dois suportes antes de soltar.'], ['Não deixe a barra afundar no peito durante a pausa.', 'Não tente completar uma repetição que não controla sem auxílio.'])
incluir('Supino reto com halteres com pegada neutra', 'Deite no banco reto com os pés firmes e um halter em cada mão. As palmas ficam voltadas uma para a outra.', ['Posicione os halteres ao lado do peito e mantenha os punhos alinhados.', 'Empurre os pesos para cima conservando as palmas voltadas entre si.', 'Abaixe devagar até uma amplitude confortável, sem bater os halteres.'], ['Não gire as mãos para outra pegada durante a repetição.', 'Não use impulso ou levante o quadril.'])
incluir('Supino fechado|Supino fechado com halteres', 'Deite em banco reto com os pés apoiados. Use barra com pegada aproximadamente na largura dos ombros ou os halteres indicados no nome, próximos entre si.', ['Mantenha punhos alinhados e cotovelos mais próximos do corpo.', 'Abaixe a carga de forma controlada em direção ao peito.', 'Empurre sem perder o apoio das costas; organize a saída antes de começar.'], ['Não junte as mãos a ponto de dobrar os punhos.', 'Não abra os cotovelos de forma brusca ou quique a carga.'])
for (const [nome, unilateral, kettlebell] of [
  ['Supino reto com halteres no solo', false, false], ['Supino reto unilateral com halter no solo', true, false], ['Supino alternado no solo com kettlebell', true, true],
] as const) incluir(nome, `Deite no chão com joelhos flexionados. Segure ${kettlebell ? 'os kettlebells com as alças firmes e o corpo dos pesos apoiado no lado externo dos antebraços' : unilateral ? 'um halter acima do peito' : 'um halter em cada mão acima do peito'}.`,
  ['Abaixe o peso até a parte de trás do braço tocar suavemente o chão.', 'Empurre para cima sem deixar o quadril ou as costelas girarem.', unilateral ? 'Complete o lado ou alterne os braços conforme o treino, estabilizando o braço que espera.' : 'Mantenha os dois pesos sob controle durante a subida e a descida.'], ['Não bata os cotovelos no chão.', 'Não solte a carga de lado para terminar a série.'])
incluir('Supino em pé na polia|Supino em pé com elástico', 'Prenda as resistências atrás de você, aproximadamente na altura do peito. No elástico, confirme a integridade e a fixação; mantenha um pé à frente para equilibrar.', ['Segure as alças ao lado do peito, com punhos alinhados.', 'Empurre as mãos para a frente, sem arquear as costas.', 'Retorne devagar, mantendo a base firme e o controle da resistência.'], ['Não deixe o elástico roçar ou apontar para o rosto.', 'Não use o balanço do tronco para empurrar.'])
incluir('Supino reto na polia', 'Posicione um banco reto entre duas polias baixas, de forma estável. Deite com os pés apoiados e leve as alças para os lados do peito.', ['Mantenha os punhos acima dos cotovelos.', 'Empurre as alças para cima sobre o peito sem bater as mãos.', 'Retorne com controle; peça ajuda para posicionar ou retirar as alças se necessário.'], ['Não deixe o cabo puxar os ombros para trás além do confortável.', 'Não use um banco que se mova com a tensão dos cabos.'])
incluir('Crucifixo com halteres|Crucifixo inclinado com halteres', 'Use um banco reto ou inclinado conforme o exercício. Deite com os pés firmes e segure os halteres acima do peito, palmas voltadas entre si.', ['Mantenha uma pequena flexão dos cotovelos e abra os braços em arco.', 'Pare antes de perder o controle ou sentir desconforto no ombro.', 'Feche o arco sobre o peito sem transformar o movimento em um supino.'], ['Não estique os cotovelos rigidamente.', 'Não desça os pesos buscando alongamento máximo a qualquer custo.'])
for (const [nomes, inicio, final] of [
  ['Crossover na polia|Crucifixo na polia média', 'na altura dos ombros', 'à frente do peito'],
  ['Crucifixo na polia alta', 'acima dos ombros', 'à frente e um pouco abaixo do peito'],
  ['Crucifixo na polia baixa', 'próximas do chão', 'à frente da parte superior do peito'],
] as const) incluir(nomes, `Ajuste duas polias ${inicio}. Segure as alças, dê um passo à frente e mantenha uma base estável.`, ['Mantenha os cotovelos levemente flexionados e o tronco firme.', `Aproxime as mãos em arco ${final}, sem girar o corpo.`, 'Reabra os braços devagar, respeitando a mobilidade dos ombros.'], ['Não use a inclinação do tronco para arrastar a carga.', 'Não deixe os cabos puxarem os braços para trás sem controle.'])
incluir('Crucifixo deitado na polia|Voador inclinado na polia', 'Posicione um banco estável entre duas polias baixas; use a inclinação indicada no exercício. Deite e segure as alças com os braços acima do peito.', ['Abra os braços lentamente mantendo uma pequena flexão dos cotovelos.', 'Pare em uma amplitude confortável, sem perder o apoio do tronco.', 'Feche os braços em arco sem bater as mãos.'], ['Não transforme o movimento em uma extensão dos cotovelos.', 'Não solte as alças sem antes organizar uma saída segura.'])
incluir('Crucifixo na máquina|Voador inclinado na máquina|Voador em pé na máquina', 'Regule a máquina para que os braços e alças fiquem em uma altura confortável para o peito. Use o assento ou a plataforma previstos para o modelo.', ['Apoie o corpo e mantenha uma pequena flexão dos cotovelos.', 'Feche os braços acompanhando o arco do equipamento.', 'Retorne lentamente sem forçar os ombros para trás.'], ['Não improvise a posição em pé em uma máquina feita para sentar.', 'Não deixe a carga voltar de uma vez.'])
incluir('Pullover com halter', 'Deite ao longo de um banco reto, com cabeça e quadril apoiados. Segure um halter de forma segura com as duas mãos acima do peito.', ['Mantenha os cotovelos levemente flexionados.', 'Leve o halter para trás da cabeça apenas até onde consegue manter as costelas e a lombar estáveis.', 'Retorne sobre o peito em um arco controlado.'], ['Não arqueie as costas para ganhar amplitude.', 'Não use um halter ou uma pegada que não consiga segurar com segurança.'])
for (const [nome, apoio] of [
  ['Flexão de braços inclinada', 'as mãos em um banco ou suporte firme e os pés no chão'], ['Flexão de braços declinada', 'os pés em um banco firme e as mãos no chão'], ['Flexão de braços ajoelhado', 'as mãos e os joelhos em um colchonete'], ['Flexão de braços fechada', 'as mãos no chão próximas da largura dos ombros, sem forçar os punhos'],
] as const) incluir(nome, `Posicione ${apoio}. Alinhe cabeça, tronco e quadril e firme o abdômen.`, ['Flexione os cotovelos para aproximar o peito da superfície de apoio das mãos.', 'Mantenha o corpo alinhado durante a descida.', 'Empurre para retornar, sem deixar a lombar afundar.'], ['Não deixe o quadril cair ou subir primeiro.', 'Não force a posição das mãos se os punhos doerem.'])
incluir('Flexão de braços com elástico', 'Passe um elástico íntegro pela parte superior das costas e prenda as pontas sob as mãos. Não passe pela nuca; organize os apoios como em uma flexão.', ['Abaixe o peito com controle, mantendo o corpo alinhado.', 'Empurre contra a resistência sem deslocar as mãos.', 'Termine apoiando os joelhos antes de retirar o elástico.'], ['Não use elástico desgastado ou que possa escapar das mãos.', 'Não deixe a lombar afundar para vencer a resistência.'])

for (const [nomes, pegada] of [
  ['Puxada aberta com pegada pronada', 'barra com palmas para a frente e mãos um pouco além dos ombros'], ['Puxada neutra|Puxada aberta com pegada neutra', 'alças com palmas voltadas uma para a outra'], ['Puxada fechada com pegada supinada', 'barra com palmas voltadas para você, em largura confortável'],
] as const) incluir(nomes, `Sente na puxada alta com as coxas presas pelo apoio. Segure ${pegada}.`, ['Mantenha o tronco firme com uma pequena inclinação para trás.', 'Conduza os cotovelos para baixo e puxe à frente do corpo.', 'Retorne devagar até estender os braços sem perder os apoios.'], ['Não puxe atrás da nuca.', 'Não use balanço nem deite o tronco para completar a repetição.'])
incluir('Puxada frontal articulada|Puxada aberta na máquina articulada|Puxada cruzada na máquina articulada', 'Ajuste assento e apoio das coxas. Confira no equipamento quais alças e trajetórias correspondem à variação escolhida.', ['Segure as alças e mantenha o corpo apoiado.', 'Puxe os cotovelos para baixo seguindo o arco da máquina, sem cruzar cabos ou braços por conta própria.', 'Retorne lentamente e mantenha os dois lados controlados.'], ['Não adapte uma máquina diferente apenas para reproduzir o nome.', 'Não eleve o quadril ou bata a carga.'])
incluir('Puxada unilateral na polia alta', 'Use uma alça individual na polia alta. Sente em uma posição estável de frente para a polia, com o braço estendido à frente e acima.', ['Conduza o cotovelo para baixo em direção ao lado do tronco.', 'Mantenha ombros e quadril voltados para a frente.', 'Retorne devagar e repita do outro lado.'], ['Não gire o tronco para puxar mais carga.', 'Não deixe o ombro ser puxado bruscamente para cima.'])
incluir('Puxada alta ajoelhado na polia', 'Ajoelhe em um apoio confortável de frente para a polia alta, mantendo a linha do cabo livre e uma base estável.', ['Segure o puxador com os braços acima e à frente.', 'Puxe os cotovelos para baixo sem arquear a lombar.', 'Retorne com controle sem deixar o corpo ser levantado pela carga.'], ['Não escolha uma carga que tire seus joelhos do apoio.', 'Não faça a puxada atrás da cabeça.'])
incluir('Pullover na polia|Pulldown com barra reta|Pulldown inclinado na polia', 'Prenda uma barra na polia alta. Fique de frente com joelhos levemente flexionados; no inclinado, leve o quadril para trás e incline o tronco de modo estável.', ['Comece com os braços à frente e cotovelos levemente flexionados.', 'Leve a barra em arco para perto das coxas, mantendo quase constante o ângulo dos cotovelos.', 'Retorne lentamente até onde os ombros permitem sem arquear a lombar.'], ['Não transforme o movimento em uma extensão de tríceps.', 'Não balance o tronco para empurrar a barra.'])
incluir('Pullover na máquina com anilhas', 'Regule o assento e os apoios de braços conforme o modelo. Ajuste o início do arco para uma posição confortável e confira a trava de entrada.', ['Sente com o tronco apoiado e posicione os braços nos apoios.', 'Conduza os braços para baixo acompanhando o arco da máquina.', 'Volte devagar sem perder o apoio das costas.'], ['Não deixe a máquina forçar os ombros além da mobilidade disponível.', 'Não tire o quadril do assento para terminar o arco.'])
for (const [nome, pegada, ajuda] of [
  ['Barra fixa|Barra fixa com pegada pronada', 'palmas para a frente', ''], ['Barra fixa com pegada supinada', 'palmas voltadas para você', ''], ['Barra fixa com elástico', 'palmas para a frente', 'Use uma assistência de elástico fixada de forma segura e peça ajuda para entrar e sair.'],
  ['Barra fixa no Graviton com pegada pronada', 'palmas para a frente', 'Regule a assistência e use a plataforma de joelhos ou pés conforme o fabricante.'], ['Barra fixa no Graviton com pegada supinada', 'palmas voltadas para você', 'Regule a assistência e use a plataforma de joelhos ou pés conforme o fabricante.'], ['Barra fixa no Graviton com pegada neutra', 'palmas voltadas uma para a outra', 'Regule a assistência e use a plataforma de joelhos ou pés conforme o fabricante.'],
] as const) incluir(nome, `Segure uma barra firme com ${pegada}, em largura confortável. ${ajuda || 'Use um apoio para alcançar a barra sem saltar de forma descontrolada.'}`, ['Firme o tronco e inicie a subida conduzindo os cotovelos para baixo.', 'Aproxime a parte superior do peito da barra sem projetar o queixo.', 'Desça devagar até uma extensão confortável dos braços.', 'Use o apoio para encerrar sem cair ou soltar a plataforma de assistência.'], ['Não balance as pernas para completar a subida.', 'Não deixe os ombros receberem um tranco na descida.'])
for (const [nomes, equipamento, pegada] of [
  ['Remada curvada|Remada curvada com pegada pronada', 'barra', 'palmas para trás'], ['Remada curvada com pegada supinada', 'barra', 'palmas para a frente'], ['Remada curvada com halteres', 'dois halteres', 'palmas voltadas entre si'], ['Remada curvada no Smith', 'barra do Smith, com travas ajustadas', 'palmas para trás'], ['Remada curvada na polia', 'puxador de uma polia baixa', 'pegada confortável'], ['Remada curvada com elástico', 'elástico íntegro preso de forma segura à frente ou sob os pés', 'pegada firme'],
] as const) incluir(nomes, `Segure ${equipamento}, com ${pegada}. Leve o quadril para trás e incline o tronco, mantendo os joelhos levemente flexionados.`, ['Sustente o tronco estável com os braços estendidos.', 'Puxe os cotovelos para trás levando a carga em direção à cintura.', 'Desça devagar sem alterar a posição do quadril.'], ['Não arredonde as costas nem jogue o tronco para cima.', 'Não use carga que impeça manter a posição de inclinação.'])
for (const [nomes, pegada] of [
  ['Remada baixa com triângulo', 'triângulo, com as palmas voltadas entre si'], ['Remada baixa sentada com pegada pronada', 'barra, com as palmas para baixo'], ['Remada baixa sentada com pegada supinada', 'barra, com as palmas para cima'], ['Remada aberta na polia com corda', 'corda, com espaço para levar os cotovelos para trás e um pouco para os lados'],
] as const) incluir(nomes, `Sente de frente para uma polia baixa, pés apoiados e joelhos levemente flexionados. Segure ${pegada}.`, ['Mantenha o tronco ereto sem travar a respiração.', 'Puxe em direção ao tronco conduzindo os cotovelos para trás.', 'Retorne com controle sem se curvar para alcançar mais longe.'], ['Não deite o tronco para vencer a carga.', 'Não eleve os ombros nem dobre os punhos.'])
incluir('Remada na máquina|Remada aberta na máquina com pegada pronada|Remada aberta na máquina com pegada neutra|Remada na máquina com anilhas com pegada pronada|Remada na máquina com anilhas com pegada neutra', 'Ajuste assento e apoio do peito conforme o equipamento. Escolha as alças de pegada pronada ou neutra indicadas no nome.', ['Mantenha pés e tronco apoiados e estenda os braços sem perder a postura.', 'Puxe as alças, conduzindo os cotovelos para trás no trajeto da máquina.', 'Retorne lentamente até a posição inicial.'], ['Não tire o peito do apoio para puxar mais longe.', 'Não solte a carga ou eleve os ombros.'])
incluir('Remada unilateral na máquina com anilhas|Remada unilateral sentada no cabo|Remada unilateral curvada no cabo', 'Use a alça individual do equipamento indicado. Na versão sentada, apoie os pés; na curvada, leve o quadril para trás e estabilize o tronco.', ['Comece com o braço estendido e ombros voltados para a frente.', 'Puxe o cotovelo para trás em direção ao quadril.', 'Retorne devagar sem girar o tronco e depois troque o lado.'], ['Não use rotação do tronco para ampliar a puxada.', 'Não deixe a carga arrastar seu ombro no retorno.'])
incluir('Remada no banco inclinado|Remada deitada|Remada deitada na barra T', 'Use o apoio de peito indicado para a variação: banco inclinado com halteres, banco alto com carga livre ou apoio próprio da barra T. Confira espaço para a carga se mover.', ['Apoie o peito e mantenha a cabeça alinhada ao tronco.', 'Puxe a carga conduzindo os cotovelos para trás.', 'Abaixe com controle sem tirar o peito do apoio.'], ['Não improvise um banco alto instável.', 'Não jogue a cabeça ou tire o peito do apoio.'])
incluir('Remada cavalinho|Remada unilateral com landmine', 'Prenda uma ponta da barra em um landmine ou suporte próprio. Posicione-se sobre a barra com joelhos flexionados e quadril para trás; na unilateral, fique ao lado da barra.', ['Segure a alça apropriada sem ficar com os dedos sob as anilhas.', 'Puxe a extremidade da barra em direção ao tronco com os cotovelos para trás.', 'Retorne devagar sem alterar a inclinação do corpo.'], ['Não use uma ponta de barra solta que possa escapar.', 'Não arredonde as costas ou levante o tronco a cada repetição.'])
incluir('Remada serrote com kettlebell', 'Apoie uma mão em um banco firme e mantenha os pés no chão. Segure o kettlebell na mão livre com o tronco inclinado e estável.', ['Deixe a carga abaixo do ombro com o braço estendido.', 'Puxe o cotovelo em direção ao quadril sem girar o corpo.', 'Abaixe com controle e depois troque o lado.'], ['Não rode o quadril para levantar o peso.', 'Não deixe o ombro cair bruscamente na descida.'])
incluir('Remada sentada com elástico', 'Sente com o tronco ereto e fixe um elástico íntegro a um ponto firme à frente, próximo da altura da cintura.', ['Segure as pontas com os braços estendidos e alguma tensão.', 'Puxe os cotovelos para trás sem inclinar o tronco.', 'Estenda os braços devagar mantendo a fixação sob observação.'], ['Não prenda o elástico a um objeto que possa se soltar.', 'Não deixe a resistência puxar seu corpo para a frente.'])
incluir('Remada invertida', 'Use uma barra fixa em suporte firme. Fique sob ela, com os pés apoiados e o corpo alinhado; quanto mais horizontal, maior a dificuldade.', ['Segure a barra e mantenha o abdômen firme.', 'Flexione os cotovelos para aproximar o peito da barra.', 'Retorne devagar sem deixar o quadril cair.'], ['Não use uma barra que possa girar ou desencaixar.', 'Não projete a cabeça para tentar alcançar a barra.'])

for (const [nomes, posicao, carga] of [
  ['Desenvolvimento com halteres', 'sentado, com encosto firme e pés apoiados', 'um halter em cada mão'], ['Desenvolvimento em pé com halteres', 'em pé, com pés firmes e joelhos destravados', 'um halter em cada mão'], ['Desenvolvimento com barra|Desenvolvimento em pé com barra', 'em pé, com pés firmes e uma barra à frente dos ombros', 'a barra com mãos um pouco além dos ombros'], ['Desenvolvimento no Smith', 'sentado em um banco com encosto, sob a barra do Smith e com as travas reguladas', 'a barra à frente dos ombros'], ['Desenvolvimento na máquina|Desenvolvimento na máquina com pegada neutra', 'sentado na máquina com as costas apoiadas e as alças próximas dos ombros', 'as alças na pegada prevista no exercício'], ['Desenvolvimento sentado com halteres com pegada neutra', 'sentado com as costas apoiadas', 'dois halteres, com as palmas voltadas entre si'], ['Desenvolvimento em pé com kettlebell', 'em pé com o tronco firme', 'os kettlebells na posição de apoio à frente dos ombros, sem dobrar os punhos'], ['Desenvolvimento na polia', 'em pé entre duas polias baixas, sem cruzar os cabos', 'as alças à altura dos ombros'],
] as const) incluir(nomes, `Posicione-se ${posicao}. Segure ${carga}.`, ['Firme o abdômen e alinhe mãos e antebraços.', 'Empurre acima da cabeça sem arquear a lombar ou projetar as costelas.', 'Retorne lentamente até a posição inicial confortável.', 'Na máquina ou no Smith, confira o encaixe e as travas antes de sair.'], ['Não empurre a carga atrás da cabeça.', 'Não use impulso das pernas em uma série de desenvolvimento estrito.'])
incluir('Desenvolvimento Arnold com halteres', 'Sente em banco com encosto. Comece com os halteres à frente dos ombros, palmas voltadas para você e cotovelos abaixo das mãos.', ['Eleve os halteres enquanto abre os cotovelos e gira gradualmente as palmas para a frente.', 'Termine acima dos ombros sem arquear as costas.', 'Inverta o movimento lentamente até a posição inicial.'], ['Não force a rotação do ombro em uma amplitude dolorosa.', 'Não acelere o giro dos punhos ou bata os halteres.'])
incluir('Desenvolvimento alternado com kettlebell', 'Fique em pé com dois kettlebells apoiados à frente dos ombros. Mantenha os punhos alinhados e o tronco estável.', ['Empurre um kettlebell acima da cabeça enquanto o outro fica apoiado.', 'Abaixe de forma controlada até o ombro.', 'Repita com o outro braço sem inclinar o corpo para os lados.'], ['Não faça impulso das pernas sem essa indicação no treino.', 'Não deixe o peso virar sobre o punho.'])
incluir('Desenvolvimento ajoelhado unilateral|Desenvolvimento ajoelhado unilateral com base alternada', 'Use um halter ou kettlebell no lado trabalhado. Ajoelhe sobre um colchonete; na base alternada, apoie um pé à frente e o outro joelho no chão.', ['Posicione a carga junto ao ombro e firme o abdômen.', 'Empurre acima da cabeça sem girar o tronco.', 'Retorne devagar e depois organize os apoios para trocar o lado.'], ['Não compense inclinando a lombar.', 'Não force o joelho contra uma superfície dura.'])
incluir('Elevação lateral com halteres sentado|Elevação lateral com halteres inclinado|Elevação lateral unilateral no banco inclinado', 'Use halteres leves e um banco estável. Na versão sentada, mantenha o tronco ereto; na inclinada, deite de lado no banco inclinado, com o braço livre voltado para cima.', ['Mantenha uma pequena flexão dos cotovelos.', 'Eleve o braço para o lado sem encolher o ombro.', 'Abaixe lentamente mantendo o mesmo apoio; na unilateral, repita do outro lado.'], ['Não mova o tronco para ganhar altura.', 'Não eleve além da amplitude confortável do ombro.'])
incluir('Elevação lateral na polia|Elevação lateral unilateral na polia|Elevação lateral inclinada na polia', 'Use uma alça na polia baixa. Fique de lado para o equipamento; na inclinada, segure um apoio firme com a mão livre e incline o corpo de forma controlada.', ['Segure a alça com a mão mais afastada e mantenha o cotovelo levemente flexionado.', 'Eleve o braço lateralmente até aproximadamente a altura do ombro.', 'Retorne devagar, sem deixar a tensão girar seu tronco.'], ['Não fique no trajeto do cabo com os pés.', 'Não dê arrancos nem levante o ombro junto com o braço.'])
incluir('Elevação lateral na máquina', 'Ajuste o assento para alinhar os ombros ao eixo do equipamento. Apoie os braços ou antebraços nos locais indicados pelo fabricante.', ['Mantenha o tronco apoiado e segure as alças se houver.', 'Afaste os braços seguindo o arco da máquina.', 'Retorne devagar sem deixar as placas baterem.'], ['Não erga o tronco para mover os apoios.', 'Não use uma regulagem que pressione diretamente os cotovelos de forma desconfortável.'])
for (const [nomes, inicio, alterna] of [
  ['Elevação frontal|Elevação frontal com halteres', 'em pé com halteres à frente das coxas', false], ['Elevação frontal com barra', 'em pé segurando uma barra à frente das coxas', false], ['Elevação frontal sentado com halteres', 'sentado com halteres ao lado das coxas', false], ['Elevação frontal alternada sentado com halteres', 'sentado com halteres ao lado das coxas', true], ['Elevação frontal no banco inclinado', 'reclinado em banco inclinado, com a carga indicada e os braços ao lado do corpo', false], ['Elevação frontal unilateral na polia', 'em pé com uma alça de polia baixa na mão trabalhada', false], ['Elevação frontal na polia com barra reta', 'em pé com uma barra reta presa à polia baixa, sem deixar o cabo roçar o corpo', false],
] as const) incluir(nomes, `Comece ${inicio}. Mantenha os cotovelos levemente flexionados e os punhos alinhados.`, ['Eleve a carga à frente do corpo até aproximadamente a altura dos ombros.', 'Abaixe lentamente sem inclinar o tronco para trás.', alterna ? 'Alterne os braços, deixando o outro peso estável ao lado do corpo.' : 'Repita mantendo a mesma flexão dos cotovelos.'], ['Não balance o corpo ou dê impulso com as pernas.', 'Não eleve os ombros em direção às orelhas.'])
incluir('Elevação lateral e frontal com halteres', 'Fique em pé com dois halteres leves, braços ao lado e tronco estável.', ['Eleve os braços para os lados até uma altura confortável e abaixe.', 'Faça a elevação à frente até aproximadamente a altura dos ombros e abaixe.', 'Alterne as duas direções sem acelerar a troca.'], ['Não una as duas direções com um giro brusco do ombro.', 'Não balance o corpo para completar a sequência.'])
incluir('Elevação de ombro em Y|Elevação Y no cabo', 'Use resistência leve. Na versão no cabo, utilize duas polias baixas; mantenha a base firme e as mãos à frente do corpo.', ['Com cotovelos levemente flexionados, eleve os braços na diagonal formando um Y.', 'Pare na altura que mantém confortável e controlada para os ombros.', 'Retorne devagar sem projetar o tronco para trás.'], ['Não force a amplitude acima da cabeça.', 'Não use uma carga que faça encolher os ombros ou dobrar os cotovelos.'])
for (const [nomes, apoio] of [
  ['Crucifixo inverso|Crucifixo inverso curvado com halteres', 'incline o tronco a partir dos quadris, com joelhos levemente flexionados'], ['Crucifixo inverso sentado com halteres', 'sente em um banco e incline o tronco para a frente, com os pés firmes'], ['Crucifixo inverso no banco inclinado', 'deite de barriga para baixo em banco inclinado, com peito apoiado e braços pendentes'],
] as const) incluir(nomes, `Segure um halter em cada mão e ${apoio}. Mantenha a cabeça alinhada ao tronco.`, ['Com pequena flexão dos cotovelos, abra os braços para os lados.', 'Eleve até onde consegue manter os ombros confortáveis e o tronco parado.', 'Abaixe devagar sem transformar o arco em uma remada.'], ['Não jogue os halteres para cima com impulso.', 'Não levante a cabeça nem arredonde a lombar.'])
incluir('Crucifixo inverso na polia|Crucifixo inverso unilateral na polia média', 'Regule as polias próximas da altura dos ombros. Segure a alça do lado oposto; na versão bilateral, organize os cabos cruzados à frente sem que rocem o pescoço.', ['Mantenha os cotovelos levemente flexionados.', 'Abra o braço para trás e para o lado sem girar o tronco.', 'Retorne devagar; na unilateral, repita do outro lado.'], ['Não puxe com os cotovelos dobrando como em uma remada.', 'Não force o braço para trás da amplitude confortável.'])
incluir('Crucifixo inverso na máquina', 'Sente voltado para o encosto da máquina de voador reverso. Regule o assento e o início do arco para alinhar as alças aos ombros.', ['Apoie o peito e segure as alças previstas para a posição reversa.', 'Abra os braços sem perder o contato do peito.', 'Retorne devagar sem bater as placas.'], ['Não improvise uma posição reversa se a máquina não permitir.', 'Não encolha os ombros ou empurre o tronco para trás.'])
incluir('Face pull', 'Use uma corda na polia próxima da altura do rosto. Fique de frente com os pés firmes e segure as pontas.', ['Puxe a corda em direção ao rosto, levando as mãos para os lados dele.', 'Deixe os cotovelos se afastarem sem elevar os ombros ou arquear a lombar.', 'Estenda os braços devagar para voltar.'], ['Não aponte o cabo para os olhos nem solte a corda sob tensão.', 'Não use uma carga que obrigue a jogar o corpo para trás.'])
for (const [nomes, carga] of [
  ['Remada alta com barra reta|Remada alta com barra W', 'a barra indicada, com mãos em largura confortável'], ['Remada alta com halteres', 'dois halteres à frente das coxas'], ['Remada alta com kettlebell', 'um kettlebell com as duas mãos'], ['Remada alta com anilha', 'uma anilha com pegada segura nas laterais'], ['Remada alta na polia', 'uma barra presa à polia baixa'],
] as const) incluir(nomes, `Fique em pé segurando ${carga}. Mantenha os pés firmes e use pouca carga ao aprender.`, ['Leve os cotovelos para cima e para os lados, mantendo a carga próxima do corpo.', 'Pare antes de desconforto nos ombros, sem precisar superar a altura deles.', 'Abaixe lentamente, mantendo os punhos alinhados.'], ['Não force os cotovelos para uma altura dolorosa.', 'Não use impulso nem dobre os punhos para aumentar a amplitude.'])
for (const [nomes, carga] of [
  ['Encolhimento com halteres', 'um halter de cada lado do corpo'], ['Encolhimento com barra reta', 'uma barra à frente das coxas'], ['Encolhimento com barra hexagonal', 'as alças da barra hexagonal, centralizando o corpo dentro dela'], ['Encolhimento no Smith', 'a barra do Smith à frente das coxas, com travas reguladas'], ['Encolhimento por trás no Smith', 'a barra do Smith atrás das coxas, somente se a posição for confortável'], ['Encolhimento na polia', 'uma barra da polia baixa'], ['Encolhimento na máquina com anilhas', 'as alças da máquina regulada para sua altura'],
] as const) incluir(nomes, `Fique com o tronco ereto e segure ${carga}. Mantenha braços estendidos sem travar os cotovelos.`, ['Eleve os ombros em direção às orelhas sem movimentar a cabeça.', 'Faça uma breve transição no alto sem girar os ombros.', 'Abaixe com controle até a posição inicial.'], ['Não faça círculos com os ombros sob carga.', 'Não dobre os cotovelos nem dê impulso com as pernas.'])
incluir('Rotação externa de ombro na polia|Rotação interna de ombro na polia', 'Regule a polia à altura do cotovelo. Segure uma alça com o cotovelo flexionado e próximo ao corpo; use resistência leve.', ['Na externa, fique com o lado trabalhado mais longe da polia e gire a mão para fora.', 'Na interna, fique com o lado trabalhado perto da polia e gire a mão em direção ao abdômen.', 'Retorne devagar mantendo cotovelo e tronco estáveis.'], ['Não afaste o cotovelo do corpo para ampliar o giro.', 'Não force a amplitude nem faça movimentos rápidos.'])

for (const [nomes, preparacao, movimento] of [
  ['Rosca direta com barra W', 'Fique em pé com uma barra W e escolha a parte inclinada que deixa seus punhos confortáveis.', 'Flexione os cotovelos para elevar a barra W sem deslocar os braços para a frente.'],
  ['Rosca com halteres', 'Fique em pé com um halter em cada mão, palmas para a frente e cotovelos junto ao corpo.', 'Eleve os dois halteres flexionando os cotovelos sem mover o tronco.'],
  ['Rosca sentado com halteres', 'Sente em um banco firme com um halter em cada mão, pés apoiados e braços ao lado.', 'Eleve os halteres com as palmas voltadas para cima sem levantar os ombros.'],
  ['Rosca alternada sentado com halteres', 'Sente com os pés apoiados e os halteres ao lado do corpo, palmas voltadas para as coxas.', 'Eleve um halter girando gradualmente a palma para cima; abaixe e alterne o braço.'],
  ['Rosca inclinada', 'Recline-se em um banco inclinado, com costas e cabeça apoiadas e halteres pendentes ao lado do tronco.', 'Flexione os cotovelos sem levar os braços para a frente nem perder o apoio das costas.'],
  ['Rosca concentrada', 'Sente com os pés afastados e apoie a parte de trás do braço na face interna da coxa, segurando um halter.', 'Flexione o cotovelo para aproximar o halter do ombro sem tirar o braço do apoio.'],
  ['Rosca drag com barra', 'Fique em pé com a barra à frente das coxas e as palmas voltadas para a frente.', 'Flexione os cotovelos levando-os um pouco para trás, enquanto a barra sobe próxima do tronco.'],
  ['Rosca inversa|Rosca inversa com barra reta', 'Fique em pé com uma barra e as palmas voltadas para baixo; escolha uma carga menor que na rosca comum.', 'Flexione os cotovelos conservando a pegada pronada e os punhos firmes.'],
] as const) incluir(nomes, preparacao, [movimento, 'Pare antes de precisar usar os ombros ou o balanço do tronco.', 'Retorne devagar até uma extensão confortável dos cotovelos.'], ['Não balance o corpo para iniciar a subida.', 'Não dobre os punhos nem deixe o peso despencar.'])
for (const [nomes, carga] of [
  ['Rosca Scott|Rosca Scott com barra reta', 'barra reta com palmas para cima'], ['Rosca Scott com barra W', 'barra W em uma pegada confortável'], ['Rosca Scott com halteres', 'halteres com palmas para cima'], ['Rosca Scott na máquina|Rosca na máquina', 'as alças da máquina, seguindo seu trajeto'],
] as const) incluir(nomes, `Ajuste o banco Scott para apoiar a parte de trás dos braços sem pressionar as axilas. Segure ${carga}.`, ['Mantenha os pés apoiados e os braços em contato com o suporte.', 'Flexione os cotovelos sem levantar o peito.', 'Abaixe lentamente, sem forçar o final da extensão.'], ['Não use impulso ao começar com os braços estendidos.', 'Não deixe o cotovelo perder contato com o apoio.'])
incluir('Rosca spider com halteres|Rosca inclinada deitada com barra', 'Deite com o peito apoiado em um banco inclinado. Deixe os braços pendentes e segure os halteres ou a barra indicada no exercício.', ['Mantenha a cabeça alinhada e os pés firmes.', 'Flexione os cotovelos sem levantar os braços ou tirar o peito do banco.', 'Abaixe lentamente até uma extensão confortável.'], ['Não use um banco instável ou sem espaço para a carga.', 'Não balance os ombros para elevar o peso.'])
incluir('Rosca martelo sentado com halteres|Rosca martelo cruzada com halteres', 'Segure os halteres com palmas voltadas entre si. Na sentada, apoie os pés; na cruzada, fique em pé com o tronco estável.', ['Flexione os cotovelos sem girar os punhos.', 'Na cruzada, leve um halter na diagonal em direção ao lado oposto do peito; na sentada, suba à frente do braço.', 'Abaixe devagar e alterne os lados quando indicado.'], ['Não deixe o tronco girar acompanhando o halter.', 'Não eleve o ombro ou use impulso.'])
for (const [nomes, alca, posicao] of [
  ['Rosca na polia|Rosca na polia baixa com barra reta', 'barra reta com palmas para cima', 'de frente para a polia baixa'], ['Rosca na polia baixa com barra W', 'barra W', 'de frente para a polia baixa'], ['Rosca bilateral na polia', 'duas alças baixas', 'entre as polias baixas'], ['Rosca unilateral na polia', 'alça individual com palma para cima', 'de frente para a polia baixa'], ['Rosca inversa na polia baixa', 'barra com palmas para baixo', 'de frente para a polia baixa'], ['Rosca martelo na polia com corda', 'corda com palmas voltadas entre si', 'de frente para a polia baixa'], ['Rosca martelo cruzada na polia', 'uma ponta de corda ou alça individual em pegada neutra', 'de lado para a polia baixa'],
] as const) incluir(nomes, `Fique ${posicao}. Segure ${alca} e mantenha os pés firmes.`, ['Mantenha os cotovelos próximos ao tronco e os punhos alinhados.', nomes === 'Rosca martelo cruzada na polia' ? 'Flexione o cotovelo levando a mão na diagonal em direção ao lado oposto do peito.' : 'Flexione os cotovelos para elevar as mãos sem mover os ombros.', 'Retorne lentamente sem deixar as placas baterem; troque o lado na versão unilateral.'], ['Não incline o corpo para vencer a carga.', 'Não perca a posição do punho durante a descida.'])
incluir('Rosca unilateral na polia alta|Rosca sobre a cabeça na polia', 'Use uma ou duas alças em polias altas. Posicione os braços elevados para os lados, mantendo os ombros confortáveis e os cotovelos aproximadamente na altura deles.', ['Firme o tronco e mantenha os braços superiores parados.', 'Flexione os cotovelos para aproximar as mãos da cabeça, sem tocar o rosto.', 'Retorne devagar respeitando a amplitude do ombro.'], ['Não use uma carga que puxe os braços para trás.', 'Não encolha os ombros ou projete a cabeça para alcançar as mãos.'])
incluir('Rosca alongada unilateral na polia|Rosca inclinada na polia', 'Use alça de polia baixa e fique à frente dela, deixando o braço um pouco atrás do tronco, sem forçar o ombro.', ['Mantenha o tronco firme e o punho alinhado.', 'Flexione o cotovelo sem trazer o braço inteiro para a frente.', 'Retorne devagar sem buscar alongamento doloroso; repita do outro lado.'], ['Não estenda o ombro além do confortável.', 'Não deixe a carga arrancar o cotovelo para trás.'])
incluir('Rosca alternada com elástico', 'Prenda um elástico íntegro sob os pés ou em um ponto baixo seguro. Segure uma ponta em cada mão, braços ao lado do corpo.', ['Flexione um cotovelo mantendo o tronco ereto.', 'Abaixe devagar sem perder a pegada ou a fixação.', 'Repita com o outro braço sem balançar os ombros.'], ['Não use um elástico que possa escapar e atingir o rosto.', 'Não incline o tronco para trás para completar a subida.'])

